#include <vector>
#include <algorithm>
#include <numeric>

using namespace std;

class Solution {
public:
    long long maxSum(vector<vector<int>>& grid, vector<int>& limits, int k) {
        vector<int> candidates;
        for (size_t i = 0; i < grid.size(); i++) {
            sort(grid[i].rbegin(), grid[i].rend());
            int take = min((int)grid[i].size(), limits[i]);
            for (int j = 0; j < take; j++) {
                candidates.push_back(grid[i][j]);
            }
        }
        sort(candidates.rbegin(), candidates.rend());
        long long sum = 0;
        int takeAll = min((int)candidates.size(), k);
        for (int i = 0; i < takeAll; i++) {
            sum += candidates[i];
        }
        return sum;
    }
};

import java.util.ArrayList;
import java.util.Arrays;
import java.util.Collections;
import java.util.List;

class Solution {
    public long maxSum(int[][] grid, int[] limits, int k) {
        List<Integer> candidates = new ArrayList<>();
        for (int i = 0; i < grid.length; i++) {
            Arrays.sort(grid[i]);
            int take = Math.min(grid[i].length, limits[i]);
            for (int j = 0; j < take; j++) {
                candidates.add(grid[i][grid[i].length - 1 - j]);
            }
        }
        candidates.sort(Collections.reverseOrder());
        long sum = 0;
        int takeAll = Math.min(candidates.size(), k);
        for (int i = 0; i < takeAll; i++) {
            sum += candidates.get(i);
        }
        return sum;
    }
}

