var maxSum = function(grid, limits, k) {
    const candidates = [];
    for (let i = 0; i < grid.length; i++) {
        grid[i].sort((a, b) => b - a);
        const take = Math.min(grid[i].length, limits[i]);
        for (let j = 0; j < take; j++) {
            candidates.push(grid[i][j]);
        }
    }
    candidates.sort((a, b) => b - a);
    let sum = 0;
    const takeAll = Math.min(candidates.length, k);
    for (let i = 0; i < takeAll; i++) {
        sum += candidates[i];
    }
    return sum;
};
